query.query-string:
SELECT RECIPIENTMDN, COUNT(CLD.CORPLISTID) AS COUNT FROM DG.CORPLISTDISTINFO CLD LEFT JOIN
            DG.CORPLISTINFO CLI ON CLD.CORPLISTID = CLI.CORPLISTID WHERE CLI.LISTTYPE = 1 AND CLI.LISTDISTRIBUTIONPOLICY
            = 3 AND RECIPIENTMDN IN (MDNLIST) AND CLD.CORPLISTID IN (SUBLISTID) GROUP BY RECIPIENTMDN;

SELECT CLI.CORPLISTID,CLI.LISTDISPLAYNAME,CLI.LISTDISTRIBUTIONPOLICY,CLI.ETAG,COUNT(CLM.MEMBERMDN)
            FROM DG.CORPLISTINFO CLI LEFT JOIN DG.CORPLISTMEMBER CLM ON CLI.CORPLISTID = CLM.CORPLISTID WHERE CORPID = ?
            AND LISTTYPE = ? GROUP BY CLI.CORPLISTID, CLI.LISTDISPLAYNAME,CLI.LISTDISTRIBUTIONPOLICY,CLI.ETAG;

SELECT CGML.MEMBERMDN MEMBERMDN,COUNT(CGML.MEMBERMDN) FROM DG.CORPGROUPMEMBERLIST CGML,
            DG.CORPGROUPINFO CGI WHERE CGI.CORPGROUPID=CGML.CORPGROUPID AND CGI.CORPID=? AND MEMBERMDN IN (MDNLIST)
            GROUP BY CGML.MEMBERMDN;

UPDATE DG.CORPGROUPMEMBERLIST SET IS_SUPERVISOR = ? , CALL_INITIATE_PERMISSION = ?,
            CALL_RECEIVE_PERMISSION = ?, INCALL_PERMISSION = ?, IS_LOCWATCHER = ?, GRP_MODIFY_PERM =
            ?,IS_OSMAUTHORIZED=?,V_CALL_INITIATE_PERMISSION = ?,V_CALL_RECEIVE_PERMISSION = ?,V_INCALL_PERMISSION = ? WHERE MEMBERMDN = ? AND CORPGROUPID = ?;

SELECT CGI.CORPGROUPID, COUNT(MEMBERMDN), CGI.GROUPDISPLAYNAME, CGI.CORPID, CGI.GROUPTYPE FROM
            DG.CORPGROUPINFO CGI LEFT JOIN DG.CORPGROUPMEMBERLIST CGML ON CGI.CORPGROUPID = CGML.CORPGROUPID WHERE
            CGI.CORPGROUPID IN(GROUPIDS) GROUP BY CGI.CORPGROUPID, CGI.GROUPDISPLAYNAME,CGI.CORPID,CGI.GROUPTYPE;

SELECT CGDI.CORPGROUPID,CGDI.RECIPIENTMDN FROM DG.CORPGROUPDISTINFO CGDI LEFT JOIN
            DG.CORPGROUPINFO CGI ON CGDI.CORPGROUPID = CGI.CORPGROUPID WHERE RECIPIENTMDN IN (MDNLIST) AND CORPID=? AND
            GROUPTYPE=?;

SELECT CORPID, SERVICEAUTHSTATUS, CLIENT_TYPE, EMAIL, SUBSCRNAME, PAMACCID, ACTIVEFS1,
            DISPATCH_TYPE, LICENSE_TYPE, CLIENTPV_MAJORVERSION, ACTIVEFS2,USER_ID,MC_ID,MCPTT_COMPLIANCE FROM
            DG.POCSUBSCRINFO WHERE MDN=?;

SELECT CORPGROUPID, GROUPDISPLAYNAME, ETAG, CORPID, GROUPTYPE, AVATAR_ID, GROUP_CREATED_BY,
            IS_LARGEGROUP, GROUPMEMBERLISTID,GROUP_SHARED,POCHOME,UGWINTEROP,VIDEO_PERMISSION,HIERARCHY_ID, GRP_PROFILE_ID FROM DG.CORPGROUPINFO WHERE CORPGROUPID
            IN(GROUPIDS);

SELECT GRPMEM.MEMBERMDN, COUNT(GRPMEM.MEMBERMDN)
            FROM DG.CORPGROUPMEMBERLIST GRPMEM INNER JOIN DG.CORPGROUPINFO GRPINFO ON GRPMEM.CORPGROUPID = GRPINFO.CORPGROUPID
            WHERE GRPMEM.MEMBERMDN IN (MDNLIST) AND GRPINFO.CORPID = ? GROUP BY GRPMEM.MEMBERMDN;

SELECT CORPGROUPID, MEMBERMDN, IS_SUPERVISOR, IS_LOCWATCHER FROM DG.CORPGROUPMEMBERLIST WHERE
            CORPGROUPID IN(SELECT DISTINCT CORPGROUPID FROM DG.CORPGROUPMEMBERLIST WHERE CORPGROUPID IN(GROUPIDS) AND
            IS_LOCWATCHER = ?);

SELECT CGML.MEMBERMDN MEMBERMDN, COUNT(CGML.MEMBERMDN) FROM DG.CORPGROUPMEMBERLIST CGML,
            DG.CORPGROUPINFO CGI WHERE CGI.CORPGROUPID = CGML.CORPGROUPID AND CGI.GROUP_CREATED_BY = ? AND CGI.CORPID =
            ? AND MEMBERMDN IN (MDNLIST) GROUP BY CGML.MEMBERMDN;

SELECT C.OSMLISTID, C.OSMLISTNAME, C.ISDEFAULT, count(O.OSMLISTID) AS OSMCOUNT FROM DG.CORPOSMINFO
            C LEFT JOIN DG.OSMLISTINFO O ON (C.OSMLISTID=O.OSMLISTID) WHERE CORPID=? GROUP BY C.OSMLISTID,
            C.OSMLISTNAME, C.ISDEFAULT;

SELECT A.APNID, A.APNNAME, A.ISDEFAULT, B.PTTSERVERID, B.SIPPROXYURI, B.GEO_SIPPROXYURI,
            B.GEOREG_PRIMF5URI, B.GEOREG_GEOF5URI, B.FDSERVICEURICELL FROM DG.APNINFO A, DG.APNPROFILEINFO B WHERE
            A.APNID = B.APNID;

SELECT ROWS ? to ? r.mdn,r.SUBSCRNAME from DG.POCSUBSCRINFO r,DG.POCSUBSCRINFO p WHERE p.mc_id =
            r.mc_id and p.USERPROFILEID = ? AND (r.USERPROFILEINDEX=0 OR r.USERPROFILEINDEX IS NULL) and p.corpid = ?
            ORDER BY r.mdn asc;

SELECT
            MDN,MC_ID,LASTPROFILEUPDATETIME,MCPTT_COMPLIANCE,USERPROFILEINDEX,CLIENTPV_MAJORVERSION,ACTIVEFS2 FROM
            DG.POCSUBSCRINFO WHERE MDN IN (MDNLIST);

SELECT ROWS ? to ?
            CORPID,GRPPROFILEID,GRPPROFILENAME,GRPTYPE,AVATAR,SERVICETYPE,OSMLISTID,AUDIOCUTIN,MCXGRP,FEATURESALLOWED,CREATETIMESTAMP,UPDATETIMESTAMP,GRPPROFILESTATUS,OVERRIDEDND,GROUP_SHARED,UGWINTEROP
            FROM DG.CORPGROUPPROFILE WHERE CORPID = ?;

SELECT ROWS ? to ?
            CORPID,GRPPROFILEID,GRPPROFILENAME,GRPTYPE,AVATAR,SERVICETYPE,OSMLISTID,AUDIOCUTIN,MCXGRP,FEATURESALLOWED,CREATETIMESTAMP,UPDATETIMESTAMP,GRPPROFILESTATUS,OVERRIDEDND,GROUP_SHARED
            FROM DG.CORPGROUPPROFILE WHERE CORPID = ? AND GRPTYPE = ? ORDER BY GRPPROFILENAME;

SELECT ROWS ? to ? r.mdn,r.SUBSCRNAME,r.CORPID from DG.POCSUBSCRINFO r,DG.POCSUBSCRINFO p WHERE
            p.mc_id = r.mc_id and p.USERPROFILEID = ? AND (r.USERPROFILEINDEX=0 OR r.USERPROFILEINDEX IS NULL) AND r.SERVICEAUTHSTATUS != 10 ORDER BY
            r.mdn asc;

SELECT RECIPIENTMDN, COUNT(CLD.CORPLISTID) AS COUNT FROM DG.CORPLISTDISTINFO CLD LEFT JOIN
            DG.CORPLISTINFO CLI ON CLD.CORPLISTID = CLI.CORPLISTID WHERE CLI.LISTTYPE = 1 AND CLI.LISTDISTRIBUTIONPOLICY
            = 6 AND RECIPIENTMDN IN (MDNLIST) GROUP BY RECIPIENTMDN;

SELECT MEMBERMDN FROM DG.CORPLISTMEMBER WHERE CORPLISTID IN (SELECT CORPLISTID FROM
            DG.CORPLISTINFO WHERE CORPLISTID IN (SELECT CORPLISTID FROM DG.CORPLISTDISTINFO WHERE RECIPIENTMDN = ?) and
            LISTDISTRIBUTIONPOLICY = ?);

SELECT MEMBERMDN FROM DG.CORPLISTMEMBER WHERE CORPLISTID IN (SELECT CORPLISTID FROM
            DG.CORPLISTINFO WHERE CORPLISTID IN (SELECT CORPLISTID FROM DG.CORPLISTDISTINFO WHERE RECIPIENTMDN = ?) and
            LISTDISTRIBUTIONPOLICY != ?);

SELECT COUNT(SUBSC.MDN) FROM DG.POCSUBSCRINFO SUBSC LEFT JOIN DG.CORPCONTACTCOUNT COUNTDETAILS ON
            SUBSC.MDN = COUNTDETAILS.MDN LEFT JOIN DG.SUBSCRIBER_ADDLINFO SAI ON SAI.MDN = SUBSC.MDN WHERE CORPID = ?
            AND nvl(SUBSC.USERPROFILEINDEX,0)=0 AND SAI.FAN_ID IN (LIST);

SELECT GMC.MEMBERMDN, COUNT(GMC.CORPGROUPID) FROM DG.CORPGROUPINFO CGI LEFT JOIN
            DG.CORPGROUPMEMBERLIST GMC ON CGI.CORPGROUPID = GMC.CORPGROUPID WHERE CGI.GROUP_CREATED_BY!=2
            AND  MEMBERMDN IN (MDNLIST) GROUP BY MEMBERMDN;

SELECT GMC.MEMBERMDN, COUNT(GMC.CORPGROUPID) FROM DG.CORPGROUPINFO CGI LEFT JOIN
            DG.CORPGROUPMEMBERLIST GMC ON CGI.CORPGROUPID = GMC.CORPGROUPID WHERE CGI.GROUPTYPE=2
            AND  MEMBERMDN IN (MDNLIST) GROUP BY MEMBERMDN;

SELECT S.MDN,S.MC_ID,S.LASTPROFILEUPDATETIME,S.MCPTT_COMPLIANCE,S.USERPROFILEINDEX,
            S.CLIENTPV_MAJORVERSION,S.ACTIVEFS2, G.ETAG FROM DG.POCSUBSCRINFO S JOIN DG.XDM_DIRECTORY
            G ON S.MDN = G.MDN WHERE G.MDN IN (MDNLIST);

INSERT INTO DG.CORP_HIERARCHY_DETAILS(CORPID, HIERARCHY_ID, EXTERNAL_HIERARCHY_ID, HIERARCHY_NAME, HIERARCHY_ALIAS,
            HIERARCHY_TYPE, SEGMENT_INDICATOR, SUBSCR_DEF_PTTRADIO, FEATURE_VERSION, CREATION_TIME, UPDATE_TIME,STATUS,
            CUSTOM_FIELD_1, CUSTOM_FIELD_2) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?);

UPDATE DG.CORP_HIERARCHY_DEPTH
SET DEPTH = ?, UPDATE_TIME = ?, CUSTOM_FIELD_1 = ?, CUSTOM_FIELD_2 = ?
WHERE CORPID = ? AND ANCESTOR_HIER_ID = ? AND DESCENDANT_HIER_ID = ?;

SELECT DISTINCT chd.HIERARCHY_NAME, chd.HIERARCHY_ID  FROM DG.CORP_HIERARCHY_DETAILS chd
INNER JOIN DG.CORP_HIERARCHY_DEPTH chdp ON (chd.HIERARCHY_ID = chdp.DESCENDANT_HIER_ID)
WHERE chd.CORPID = ? ;

SELECT C.OSMLISTID, C.OSMLISTNAME, C.ISDEFAULT, count(O.OSMLISTID) AS OSMCOUNT FROM DG.CORPOSMINFO
            C LEFT JOIN DG.OSMLISTINFO O ON (C.OSMLISTID=O.OSMLISTID) WHERE C.CORPID=? AND C.HIERARCHY_ID = ? GROUP BY C.OSMLISTID,
            C.OSMLISTNAME, C.ISDEFAULT;

SELECT ROWS ? to ?
            CORPID,GRPPROFILEID,GRPPROFILENAME,GRPTYPE,AVATAR,SERVICETYPE,OSMLISTID,AUDIOCUTIN,MCXGRP,FEATURESALLOWED,CREATETIMESTAMP,UPDATETIMESTAMP,GRPPROFILESTATUS,OVERRIDEDND,GROUP_SHARED,UGWINTEROP
            FROM DG.CORPGROUPPROFILE WHERE CORPID = ? AND HIERARCHY_ID=?;

SELECT CHD.HIERARCHY_ID, CHD.HIERARCHY_NAME FROM DG.CORP_HIERARCHY_DETAILS CHD
INNER JOIN DG.CORP_HIERARCHY_DEPTH CHDP ON (CHD.CORPID = CHDP.CORPID AND  CHD.HIERARCHY_ID = CHDP.DESCENDANT_HIER_ID)
WHERE CHD.CORPID = ? AND CHDP.DEPTH=0;
